# Private child entry
# Внутренняя проверка не захватывает блокировку родительского процесса повторно.
if [[ ${1:-} == --check-internal ]]; then
    (( $# == 1 )) || die 'Внутренняя проверка не принимает дополнительные аргументы'
    require_server
    check
else
    main "$@"
fi
exit 0
